// @ts-ignore Generated by the OpenNext build.
import handler from "./.open-next/worker.js";
export default {
	fetch: handler.fetch,
	async scheduled(_event: ScheduledController, env: CloudflareEnv & {PAYMENT_PUBLIC_ORIGIN?: string; PAYMENT_RECONCILE_SECRET?: string}, ctx: ExecutionContext) {
		if (!env.PAYMENT_RECONCILE_SECRET || env.PAYMENT_PUBLIC_ORIGIN !== "https://emaalbs.com") throw new Error("Payment reconciliation is not configured");
		const response = await handler.fetch(new Request(`${env.PAYMENT_PUBLIC_ORIGIN}/api/internal/payments/reconcile`, {method:"POST",headers:{Authorization:`Bearer ${env.PAYMENT_RECONCILE_SECRET}`}}),env,ctx);
		if (!response.ok) throw new Error(`Payment reconciliation HTTP ${response.status}`);
		const result = await response.json() as {checked:number;failed:number};
		console.log("Payment reconciliation", {checked:result.checked, failed:result.failed});
		if(result.failed) throw new Error("Some payments could not be verified; retry is scheduled");
	},
};
